/**
 * ca-manager.js — Dynamic CA Certificate Authority
 *
 * Generates a root CA once (via scripts/install-ca.ps1).
 * On-demand creates ephemeral per-domain TLS certs signed by that CA.
 * Caches certs in memory — no disk writes per domain.
 */

'use strict';

const forge = require('node-forge');
const path  = require('path');
const fs    = require('fs');

let caCert = null;
let caKey  = null;
const certCache = new Map();

/**
 * Load the root CA from disk (generated by install-ca.ps1).
 */
function loadCA(certPath, keyPath) {
    const absC = path.resolve(__dirname, '..', certPath);
    const absK = path.resolve(__dirname, '..', keyPath);

    if (!fs.existsSync(absC) || !fs.existsSync(absK)) {
        throw new Error(`CA files not found. Run scripts/install-ca.ps1 first.\n  Expected: ${absC}`);
    }

    caCert = forge.pki.certificateFromPem(fs.readFileSync(absC, 'utf8'));
    caKey  = forge.pki.privateKeyFromPem(fs.readFileSync(absK, 'utf8'));
}

/**
 * Generate (or return cached) a TLS cert for a hostname, signed by our CA.
 * Returns { cert: string (PEM), key: string (PEM) }
 */
async function getCertForHost(hostname) {
    if (certCache.has(hostname)) return certCache.get(hostname);

    if (!caCert || !caKey) {
        const config = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'config.json'), 'utf8'));
        loadCA(config.mitm.ca_cert_path, config.mitm.ca_key_path);
    }

    const keys = forge.pki.rsa.generateKeyPair(2048);
    const cert = forge.pki.createCertificate();

    cert.publicKey = keys.publicKey;
    cert.serialNumber = Date.now().toString(16);
    cert.validity.notBefore = new Date();
    cert.validity.notAfter  = new Date();
    cert.validity.notAfter.setFullYear(cert.validity.notBefore.getFullYear() + 1);

    const attrs = [
        { name: 'commonName',         value: hostname },
        { name: 'organizationName',   value: 'LumaxConProxy' },
        { name: 'countryName',        value: 'SE' },
    ];
    cert.setSubject(attrs);
    cert.setIssuer(caCert.subject.attributes);

    cert.setExtensions([
        { name: 'basicConstraints', cA: false },
        { name: 'subjectAltName',   altNames: [{ type: 2, value: hostname }] },
        { name: 'extKeyUsage',      serverAuth: true },
    ]);

    cert.sign(caKey, forge.md.sha256.create());

    const result = {
        cert: forge.pki.certificateToPem(cert),
        key:  forge.pki.privateKeyToPem(keys.privateKey),
    };

    certCache.set(hostname, result);
    return result;
}

/**
 * Generate a self-signed root CA and write to disk.
 * Called by scripts/install-ca.ps1 via: node -e "require('./core/ca-manager').generateCA()"
 */
function generateCA(outDir) {
    const dir = outDir || path.join(__dirname, '..', 'ca');
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

    const keys = forge.pki.rsa.generateKeyPair(4096);
    const cert = forge.pki.createCertificate();

    cert.publicKey = keys.publicKey;
    cert.serialNumber = '01';
    cert.validity.notBefore = new Date();
    cert.validity.notAfter  = new Date();
    cert.validity.notAfter.setFullYear(cert.validity.notBefore.getFullYear() + 10);

    const attrs = [
        { name: 'commonName',       value: 'LumaxConProxy Root CA' },
        { name: 'organizationName', value: 'LUMAX Diamond Concordia' },
        { name: 'countryName',      value: 'SE' },
    ];
    cert.setSubject(attrs);
    cert.setIssuer(attrs);
    cert.setExtensions([
        { name: 'basicConstraints', cA: true },
        { name: 'keyUsage', keyCertSign: true, cRLSign: true },
        { name: 'subjectKeyIdentifier' },
    ]);
    cert.sign(keys.privateKey, forge.md.sha256.create());

    fs.writeFileSync(path.join(dir, 'ca.crt'), forge.pki.certificateToPem(cert));
    fs.writeFileSync(path.join(dir, 'ca.key'), forge.pki.privateKeyToPem(keys.privateKey));

    console.log('[CA] Root CA generated:');
    console.log('     Cert:', path.join(dir, 'ca.crt'));
    console.log('     Key: ', path.join(dir, 'ca.key'));
}

module.exports = { getCertForHost, generateCA, loadCA };
